//! 🌱️ Public bootstrap transport and real partial-context debt laws.
use semio_framework_actor_receipt::*;
use semio_framework_actor::{OriginalActorTurnWork,OriginalJobBudget,RetainedTurnInput};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
mod tests{use super::*;#[test]fn bootstrap_fixture_words_preserve_namespace_and_every_scalar(){let rows:serde_json::Value=serde_json::from_str(include_str!("../../../🌱️bootstrap/cases.json")).unwrap();for row in rows["cases"].as_array().unwrap(){let mut bytes=[0;304];bytes[..8].copy_from_slice(&[83,65,66,49,1,0,48,1]);let mut w=Vec::new();for n in row["budget"].as_array().unwrap(){w.push(n.as_str().unwrap().parse::<u64>().unwrap())}for field in["actual","prepaid","held"]{for key in["items","copy","capacity","release","work"]{w.push(row[field][key].as_str().unwrap().parse().unwrap())}}w.push(row["sequence"].as_str().unwrap().parse().unwrap());w.push(row["returned"].as_str().unwrap().parse().unwrap());w.push(row["status"].as_u64().unwrap()|(row["phase"].as_u64().unwrap()<<8)|(row["refusal"].as_u64().unwrap()<<32));for(index,n)in w.into_iter().enumerate(){bytes[8+index*8..16+index*8].copy_from_slice(&n.to_le_bytes())}let call=OriginalActorBootstrapCall::read(&bytes).unwrap();let mut out=[0;304];let mut sink=semio_framework_actor_receipt::OriginalSliceHeaderWriter::new(&mut out,304).unwrap();call.write_to(&mut sink).unwrap();assert_eq!(out,bytes);assert_eq!(call.budget.input.operation,9007199254741009);call.validate_expected(call.budget).unwrap();let mut bad=bytes;bad[..4].copy_from_slice(b"SAC3");assert!(OriginalActorBootstrapCall::read(&bad).is_err());bad=bytes;bad[298]=1;assert!(OriginalActorBootstrapCall::read(&bad).is_err());bad=bytes;bad[8+18*8]=2;assert!(OriginalActorBootstrapCall::read(&bad).is_err());bad=bytes;bad[280..288].fill(0);assert!(OriginalActorBootstrapCall::read(&bad).is_err());}}}
mod transition_tests{use super::*;
#[test]fn transition_matches_independent_shared_return_cases_and_actual_inner_escrow(){let rows:serde_json::Value=serde_json::from_str(include_str!("../../../🌱️bootstrap/transition.json")).unwrap();for row in rows["cases"].as_array().unwrap(){let mut bytes=[0u8;200];bytes[..8].copy_from_slice(&[83,66,84,49,1,0,200,0]);bytes[8..16].copy_from_slice(&[83,65,67,51,1,1,0,0]);bytes[144..148].copy_from_slice(&3000u32.to_le_bytes());bytes[148..152].copy_from_slice(&48u32.to_le_bytes());for(i,key)in["sequence","items","copy","capacity","release","work"].into_iter().enumerate(){let n=row[key].as_str().unwrap().parse::<u64>().unwrap();bytes[152+i*8..160+i*8].copy_from_slice(&n.to_le_bytes())}let parsed=OriginalActorBootstrapTransitionCall::read(&bytes);assert_eq!(parsed.is_ok(),row["valid"].as_bool().unwrap());if let Ok(parsed)=parsed{let mut out=[0;200];let mut writer=semio_framework_actor_receipt::OriginalSliceHeaderWriter::new(&mut out,200).unwrap();parsed.write_to(&mut writer).unwrap();assert_eq!(bytes,out);let mut memory=[0u8;4096];memory[32..232].copy_from_slice(&bytes);let(header,escrow)=semio_framework_actor_receipt::borrowed_scalar_escrow(&memory,(200u64<<32)|32).unwrap();assert_eq!(header,bytes);assert_eq!(escrow.len(),48);semio_framework_actor_receipt::validate_original_source_header_body(header).unwrap();bytes[12]=5;assert!(OriginalActorBootstrapTransitionCall::read(&bytes).is_err());}}}
}
mod debt_tests{use super::*;fn clock()->Option<u64>{Some(0)}
#[test]fn real_partial_context_records_exact_physical_handback_before_new_epoch_once(){let mut budget=OriginalJobBudget{input:RetainedTurnInput{operation:915,generation:2,epoch:1,grant:RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128},work:OriginalActorTurnWork{clock_binding:17,absolute_deadline_us:1000000,fuel:1000000}},retained_policy:RetainedCloneGrant{maximum_items:512,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:64},fuel:65536,deadline_us:999999,cancelled:false};let mut slot=semio_framework_actor::retained_context::OriginalActorContextSlot::empty();let mut backing=OriginalActorBootstrapReceipt::empty();for _ in 0..2{let observed=backing.observe_prior_return(budget,||slot.observe_bootstrap_return_before_begin(budget.input)).unwrap();let repeated=backing.observe_prior_return(budget,||panic!("physical return cannot be observed twice")).unwrap();assert_eq!(repeated,OriginalBootstrapEffects::default());let body=slot.admit_step(budget.input,budget.step_budget(),clock);assert!(body.result.is_ok());let actual=OriginalBootstrapEffects{progress:body.receipt_spent.checked_add(observed.progress).unwrap(),work:body.work_units_spent+observed.work};let(pointer,frame,metadata)=backing.publish(budget,actual,slot.bootstrap_phase(),OriginalActorBootstrapStatus::Pending).unwrap();let posted=slot.record_bootstrap_effects(budget.input,metadata.progress.checked_add(observed.progress).unwrap(),metadata.work+observed.work);posted.0.unwrap();posted.1.unwrap();assert!(backing.hand_back(pointer,304).unwrap());let fresh=frame.fresh().unwrap();let mut input=budget.input.return_original(fresh.progress.checked_add(frame.held.progress).unwrap(),fresh.work+frame.held.work).unwrap().remaining;input.epoch+=1;budget.input=input;}let observed=backing.observe_prior_return(budget,||slot.observe_bootstrap_return_before_begin(budget.input)).unwrap();assert_eq!(observed.progress.copied_items,1);let posted=slot.record_bootstrap_effects(budget.input,observed.progress,observed.work);posted.0.unwrap();posted.1.unwrap();budget.input=budget.input.return_original(observed.progress,observed.work).unwrap().remaining;budget.input.epoch+=1;for turn in 0..1024{if slot.terminal_is_empty(){break}let call=slot.close_step(budget.input,semio_framework_job::StepBudget::new(budget.input.work.fuel,budget.input.work.absolute_deadline_us,budget.input.grant));assert!(call.result.is_ok());let mut input=budget.input.return_original(call.receipt_spent,call.work_units_spent).unwrap().remaining;input.epoch+=1;budget.input=input;assert!(turn<1023)}assert!(slot.terminal_is_empty());}
}
#[test]fn bootstrap_first_response_quotes_a_real_birth_without_reusing_normal_producer_limit(){let(rows,demand,work)=OriginalActorBootstrapReceipt::first_bootstrap_response_reserve();let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🌱️bootstrap/cases.json")).unwrap();assert_eq!(rows,corpus["reserve"]["bootstrapItems"].as_u64().unwrap()as usize);let(birth,birth_work)=semio_framework_actor::retained_context::OriginalActorContextSlot::bootstrap_birth_reserve();assert!(demand.capacity_bytes>=birth.capacity_bytes);assert!(demand.copy_bytes>=birth.copy_bytes+304);assert!(work>=birth_work+43);for row in corpus["reserve"]["cases"].as_array().unwrap(){assert_eq!(row["items"].as_u64().unwrap()>=rows as u64,row["accepted"].as_bool().unwrap())}let input=RetainedTurnInput{operation:915,generation:2,epoch:1,grant:RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128},work:OriginalActorTurnWork{clock_binding:17,absolute_deadline_us:1000000,fuel:1000000}};let mut slot=semio_framework_actor::retained_context::OriginalActorContextSlot::empty();for fuel in[0,1]{let policy=RetainedCloneGrant{maximum_copy_bytes:0,..input.grant};let(call,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||slot.admit_step(input,semio_framework_job::StepBudget::new(fuel,input.work.absolute_deadline_us,policy),clock));assert!(!call.result.unwrap().ready);assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(slot.bootstrap_phase(),0)}assert!(slot.terminal_is_empty());}
